const c=JSON.parse(require('fs').readFileSync('.lattice/story/actives/B-137a/checklist.json','utf8'));
for(const it of c.items||[]){
  const vi=it.verificationIntent||{};
  const ids=[];
  for(const col of ['happy','edge','adversarial']) for(const i of (vi[col]||[])) ids.push(i.id);
  const ev=it.verificationEvidence||[];
  const refs=ev.map(e=>e.intentRef);
  const missing=ids.filter(i=>!refs.includes(i));
  const dup=refs.filter((r,ix)=>refs.indexOf(r)!==ix);
  const orphan=refs.filter(r=>!ids.includes(r));
  console.log(it.id,'missing=',JSON.stringify(missing),'dup=',JSON.stringify(dup),'orphan=',JSON.stringify(orphan));
  const bad=ev.filter(e=>e.result==='fail');
  if(bad.length) console.log('  FAIL results:',bad.map(e=>e.intentRef));
  const kinds={};for(const e of ev)kinds[e.kind]=(kinds[e.kind]||0)+1;
  console.log('  kinds',JSON.stringify(kinds));
}
